namespace {
using namespace mt;int checks=0;
void check(bool ok,const std::string& msg){++checks;if(!ok)throw std::runtime_error("FALLÓ: "+msg);}
template<class F>void raises(F fn,const std::string& msg){bool raised=false;try{fn();}catch(const std::exception&){raised=true;}check(raised,msg);}
Json query(const Project& p,const std::string& kind,const std::string& text=""){return agent_request(p,"query",{{"kind",kind},{"text",text},{"limit",1000},{"token_budget",100000}});}
std::string id_at(const Project& p,const std::string& name){auto files=index_snapshot(p)["files"];for(const auto& f:files)if(f["path"]==name)return f["id"];throw std::runtime_error("Fixture no inventariada: "+name);}
class Client {
    HANDLE input{},output{},process{};std::string pending;int serial=0;
public:
    Client(const fs::path& executable,const fs::path& project){
        SECURITY_ATTRIBUTES sa{sizeof(sa),nullptr,TRUE};HANDLE read{},write{};
        if(!CreatePipe(&read,&input,&sa,0)||!CreatePipe(&output,&write,&sa,0))throw std::runtime_error("pipe");
        SetHandleInformation(input,HANDLE_FLAG_INHERIT,0);SetHandleInformation(output,HANDLE_FLAG_INHERIT,0);
        auto null=CreateFileW(L"NUL",GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,&sa,OPEN_EXISTING,0,nullptr);
        STARTUPINFOW si{sizeof(si)};si.dwFlags=STARTF_USESTDHANDLES;si.hStdInput=read;si.hStdOutput=write;si.hStdError=null;
        PROCESS_INFORMATION pi{};auto cmd=quote_arg(executable.wstring())+L" mcp --project "+quote_arg(project.wstring());
        auto ok=CreateProcessW(executable.c_str(),cmd.data(),nullptr,nullptr,TRUE,CREATE_NO_WINDOW,nullptr,project.parent_path().c_str(),&si,&pi);
        CloseHandle(read);CloseHandle(write);CloseHandle(null);if(!ok)throw std::runtime_error("start MCP Win32 "+std::to_string(GetLastError()));process=pi.hProcess;CloseHandle(pi.hThread);
    }
    ~Client(){if(input)CloseHandle(input);if(process){if(WaitForSingleObject(process,10000)!=WAIT_OBJECT_0)TerminateProcess(process,99);CloseHandle(process);}if(output)CloseHandle(output);}
    void write(const Json& message){auto bytes=message.dump()+"\n";DWORD written{};if(!WriteFile(input,bytes.data(),static_cast<DWORD>(bytes.size()),&written,nullptr)||written!=bytes.size())throw std::runtime_error("MCP write");}
    Json read(){auto start=GetTickCount64();while(GetTickCount64()-start<30000){auto nl=pending.find('\n');if(nl!=std::string::npos){auto line=pending.substr(0,nl);pending.erase(0,nl+1);return Json::parse(line);}DWORD size{};if(!PeekNamedPipe(output,nullptr,0,nullptr,&size,nullptr))throw std::runtime_error("MCP EOF");if(size){char buf[8192];DWORD got{};if(ReadFile(output,buf,std::min<DWORD>(size,sizeof(buf)),&got,nullptr))pending.append(buf,got);}else Sleep(10);}throw std::runtime_error("MCP timeout");}
    Json rpc(const std::string& method,const Json& params=Json::object()){auto id=++serial;write({{"jsonrpc","2.0"},{"id",id},{"method",method},{"params",params}});auto result=read();check(result["id"]==id,"MCP correlaciona respuesta");return result;}
    Json call(const std::string& name,const Json& args=Json::object()){return rpc("tools/call",{{"name",name},{"arguments",args}});}
};
}
